local S,P=require('sm_spells'),require('sm_pvp');local R={}
function R.decide(c,e)
 if c.spec~=64 or not c.pvp or not c.settings.damage then return end
 local a;local ff=c.talent('frostfire');local fingers=c.stacks(S.aura.fingers);local ice=c.stacks(S.aura.icicles)
 -- Ray transforms into Comet Storm when the talent is present. Consume that
 -- short follow-up before the Fingers generated by Ray and even if the healer
 -- setup expires during the completed channel.
 a=c.pick('comet_storm','PvP transformed Comet immediately after Ray');if a then return a end
 -- A permitted Ray is the center of Frost's Arena kill window. Start the
 -- protected channel before spending Spike, Fingers or Brain Freeze so those
 -- instant globals cannot consume the healer-control/cast-space window.
 if c.settings.frost_ray and c.burst and c.known('ray') then
  -- The final executor applies Ray's full four-second hostile-roster scan.
  -- Keeping one authority avoids duplicate helper calls before the input.
  local ray_charges=c.charges('ray')
  local two_charge_build=c.talent('hand_final')
  local target_stunned=false
  local kill_commit=(c.target_hp and c.target_hp<=35)or e.burst_requested
  -- Only a lone reserved charge needs the target-stun query. A normal
  -- one-charge build and a capped two-charge build commit without it.
  if two_charge_build and ray_charges==1 and not kill_commit then
   target_stunned=P.control(c,c.target,'STUN',3000);kill_commit=target_stunned
  end
  if not two_charge_build or ray_charges>=2 or ray_charges==1 and kill_commit then
   a=c.pick('ray',two_charge_build and ray_charges<2 and(target_stunned and'reserved PvP Ray committed into kill-target stun'
    or e.burst_requested and'reserved PvP Ray committed by manual coordination'or'reserved PvP Ray committed below execute threshold')
    or'permitted PvP Ray before proc spending');if a then return a end
  end
 end
 -- Crystalline Refraction grants two Fingers from Ray. Convert those charges
 -- immediately after the confirmed channel before another hardcast consumes
 -- the short follow-up window. Ordinary Frost priority remains unchanged.
 local recent_ray=c.now-(e.history.ray or-math.huge)<=8
 if fingers>0 and recent_ray then
  a=c.pick('ice_lance','immediate Fingers conversion after confirmed PvP Ray');if a then return a end
 end
 if c.settings.frost_spike and (c.buff(S.aura.glacial_spike)==true or ice>=5) and c.ready('glacial_spike') then
  -- Spike needs a shorter protected window than Ray. Delay this separate scan
  -- until the proc, Icicles and spell-readiness gates have all passed.
  if P.channel_safe(c,2000)then
   a=c.pick('glacial_spike','PvP Spike with space or target control');if a then return a end
  end
 end
 if fingers>0 then a=c.pick('ice_lance','instant PvP Fingers pressure');if a then return a end end
 if ff and c.buff(S.aura.frostfire_empowerment)==true then a=c.pick('frostfire_bolt','instant PvP Frostfire pressure');if a then return a end end
 if c.buff(S.aura.brain)==true then a=c.pick('flurry','PvP Brain Freeze proc');if a then return a end end
 if c.attackers>0 and c.settings.frost_orb then
  a=c.pick('frozen_orb','PvP instant slow pressure while being trained');if a then return a end
 end
 if c.burst then
  if c.settings.frost_orb then a=c.pick('frozen_orb','permitted PvP Orb through clear path');if a then return a end end
 end
 if c.settings.frost_blizzard and c.burst and c.aoe_safe and c.buff(S.aura.freezing_rain)==true
  and (c.enemy_count>=2 or P.control(c,c.target,'STUN',1000) or P.control(c,c.target,'ROOT',1000))then
  a=c.pick('blizzard','instant PvP slow coverage after Orb');if a then return a end
 end
 if c.settings.frost_freezing and c.stacks(S.aura.freezing,true)>=(ff and 12 or 6)then a=c.pick('ice_lance','PvP Freezing spender');if a then return a end end
 if c.attackers>0 then return c.pick('ice_lance','instant kiting pressure under focus')end
 if ff then a=c.pick('frostfire_bolt','PvP Frostfire builder');if a then return a end end
 a=c.pick('frostbolt','PvP Freezing builder');if a then return a end
 if c.moving then return c.pick('ice_lance','instant pressure while kiting')end
end
return R
